#include <stdio.h>
#include <stdlib.h>

void print_pascal_triangle(int n) {
    int* row = (int*) malloc((n + 1) * sizeof(int));
    row[0] = 1;
    for (int i = 1; i <= n; i++) {
        row[i] = 1;
        for (int j = i - 1; j > 0; j--) {
            row[j] = row[j - 1] + row[j];
        }
    }
    for (int i = 0; i <= n; i++) {
        printf("%d ", row[i]);
    }
    printf("\n");
    free(row);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char* endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    print_pascal_triangle(n);
    return 0;
}
